{"file_path":"src/lcs.js","content":"/**
 * Longest common subsequence of two line arrays, comparing lines as exact
 * strings. When several subsequences share the maximum length, the one
 * returned is the one whose matches occur earliest: walking both arrays from
 * the start, a match is taken whenever the current lines are equal, and
 * otherwise the side whose remaining subsequence is at least as long as the
 * other's is advanced, preferring to advance `a` when the two are equal.
 *
 * Returns an array of `[indexInA, indexInB]` pairs, one per matched line, in
 * increasing order of both indices.
 */
export function lcsMatches(a, b) {
  const m = a.length
  const n = b.length
  const dp = new Array(m + 1)
  for (let i = 0; i <= m; i++) dp[i] = new Uint32Array(n + 1)
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < m && j < n) {
    if (a[i] === b[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}
"}

