{"file_path":"src/diff.js","content":"import { lcsMatches } from './lcs.js'

/**
 * Every stretch of `base` the LCS with `side` does not cover, described as a
 * run of base lines replaced by a run of `side`'s lines. An insertion
 * replaces zero base lines and a deletion contributes zero side lines.
 *
 * Returns changes in increasing order of `baseStart`, each shaped as
 * `{ baseStart, baseEnd, lines }` where `[baseStart, baseEnd)` is the
 * half-open range of replaced base indices and `lines` are the side's lines
 * that replace them.
 */
export function computeChanges(base, side) {
  const matches = lcsMatches(base, side)
  const changes = []
  let bi = 0
  let si = 0
  for (const [mb, ms] of [...matches, [base.length, side.length]]) {
    if (mb > bi || ms > si) {
      changes.push({ baseStart: bi, baseEnd: mb, lines: side.slice(si, ms) })
    }
    bi = mb + 1
    si = ms + 1
  }
  return changes
}
"}

