{"file_path":"src/regions.js","content":"import { computeChanges } from './diff.js'

function arraysEqual(a, b) {
  return a.length === b.length && a.every((v, i) => v === b[i])
}

function reconstruct(base, start, end, changes) {
  const result = []
  let p = start
  for (const change of changes) {
    result.push(...base.slice(p, change.baseStart))
    result.push(...change.lines)
    p = change.baseEnd
  }
  result.push(...base.slice(p, end))
  return result
}

/**
 * Groups the base into stable regions (kept unchanged) and changed regions
 * (touched by one or more changes from either side), and resolves each
 * changed region against `mine` and `theirs`.
 *
 * Returns an ordered list of entries covering the whole of `base`:
 *   - `{ type: 'stable', lines }`
 *   - `{ type: 'region', kind, mineLines, baseLines, theirsLines }`
 *     where `kind` is `'both'`, `'mine'`, `'theirs'` or `'conflict'`.
 */
export function computeRegions(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = computeChanges(base, theirs).map(c => ({ ...c, side: 'theirs' }))

  const all = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const groups = []
  let idx = 0
  while (idx < all.length) {
    let start = all[idx].baseStart
    let end = all[idx].baseEnd
    const changes = [all[idx]]
    idx++
    while (idx < all.length && all[idx].baseStart <= end) {
      end = Math.max(end, all[idx].baseEnd)
      changes.push(all[idx])
      idx++
    }
    groups.push({ baseStart: start, baseEnd: end, changes })
  }

  const entries = []
  let pointer = 0
  for (const group of groups) {
    if (group.baseStart > pointer) {
      entries.push({ type: 'stable', lines: base.slice(pointer, group.baseStart) })
    }

    const mineInRegion = group.changes.filter(c => c.side === 'mine')
    const theirsInRegion = group.changes.filter(c => c.side === 'theirs')
    const mineLines = reconstruct(base, group.baseStart, group.baseEnd, mineInRegion)
    const theirsLines = reconstruct(base, group.baseStart, group.baseEnd, theirsInRegion)
    const baseLines = base.slice(group.baseStart, group.baseEnd)

    let kind
    if (arraysEqual(mineLines, theirsLines)) kind = 'both'
    else if (arraysEqual(mineLines, baseLines)) kind = 'theirs'
    else if (arraysEqual(theirsLines, baseLines)) kind = 'mine'
    else kind = 'conflict'

    entries.push({ type: 'region', kind, mineLines, baseLines, theirsLines })
    pointer = group.baseEnd
  }
  if (pointer < base.length) {
    entries.push({ type: 'stable', lines: base.slice(pointer, base.length) })
  }

  return entries
}
"}

