{"file_path":"src/parse.js","content":"/**
 * Splits raw stdin text into the three documents it holds: mine, base and
 * theirs, separated by lines that are exactly `%%%`. Throws if the input
 * does not hold exactly three documents.
 */
export function parseInput(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') docs.push([])
    else docs[docs.length - 1].push(line)
  }

  if (docs.length !== 3) {
    throw new Error('expected three parts separated by %%%')
  }
  return docs
}
"}

