/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */
import { readFileSync } from 'node:fs'
import { parseInput } from './parse.js'
import { computeRegions } from './regions.js'
import { formatMerge, formatRegions } from './format.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.has(args[0])) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')
  let mine, base, theirs
  try {
    ;[mine, base, theirs] = parseInput(input)
  } catch (err) {
    fail(err.message)
    return
  }

  const entries = computeRegions(mine, base, theirs)

  let lines
  let conflict
  if (mode === 'merge') {
    ;({ lines, conflict } = formatMerge(entries, true))
  } else if (mode === 'merge2') {
    ;({ lines, conflict } = formatMerge(entries, false))
  } else {
    ;({ lines, conflict } = formatRegions(entries))
  }

  process.stdout.write(lines.length === 0 ? '' : lines.join('\n') + '\n')
  process.exit(conflict ? 1 : 0)
}

main()
"}

